from typing import Optional

def roman_to_integer(s: str) -> Optional[int]:
    if not isinstance(s, str) or not s:
        return None
    val_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for char in reversed(s.upper()):
        if char not in val_map:
            return None
        curr = val_map[char]
        if curr < prev:
            total -= curr
        else:
            total += curr
        prev = curr
    return total

